css:
.loader { --accent: var(--loader-color); width: var(--loader-size); height: var(--loader-size); display: grid; grid-template-columns: repeat(3, 1fr); gap: 14%; place-items: center; }
.loader span { width: 100%; aspect-ratio: 1; border-radius: 50%; background: var(--accent); animation: gwave calc(var(--loader-speed) * 1.3) ease-in-out infinite; }
.loader span:nth-child(1) { animation-delay: 0s; }
.loader span:nth-child(2), .loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .12); }
.loader span:nth-child(3), .loader span:nth-child(5), .loader span:nth-child(7) { animation-delay: calc(var(--loader-speed) * .24); }
.loader span:nth-child(6), .loader span:nth-child(8) { animation-delay: calc(var(--loader-speed) * .36); }
.loader span:nth-child(9) { animation-delay: calc(var(--loader-speed) * .48); }
@keyframes gwave { 0%, 100% { transform: scale(.4); opacity: .35; } 50% { transform: scale(1); opacity: 1; } }
